package dev.jlo.gamemodes.domain.siege;
import java.util.Objects;
public final class SiegePlayerStats { private final int kills,deaths,contribution,battleTokens; public SiegePlayerStats(){this(0,0,0,0);} public SiegePlayerStats(int kills,int deaths,int contribution,int battleTokens){this.kills=kills;this.deaths=deaths;this.contribution=contribution;this.battleTokens=battleTokens;} public int getKills(){return kills;} public int getDeaths(){return deaths;} public int getContribution(){return contribution;} public int getBattleTokens(){return battleTokens;} public SiegePlayerStats copy(int kills,int deaths,int contribution,int battleTokens){return new SiegePlayerStats(kills,deaths,contribution,battleTokens);} @Override public boolean equals(Object o){return this==o||(o instanceof SiegePlayerStats x&&kills==x.kills&&deaths==x.deaths&&contribution==x.contribution&&battleTokens==x.battleTokens);}@Override public int hashCode(){return Objects.hash(kills,deaths,contribution,battleTokens);}@Override public String toString(){return "SiegePlayerStats(kills="+kills+", deaths="+deaths+", contribution="+contribution+", battleTokens="+battleTokens+")";} }
